with lines as (select id, customer_id, coupon_codes, attr_key, v from carts lateral view explode(attributes) x as attr_key, v) select customer_id, size(collect_set(attr_key)) as num_attr_keys, count(distinct attr_key) as distinct_attr_keys, sort_array(collect_set(attr_key)) as attr_key_list, count_if(attr_key = 'utm_source') as utm_source_events from lines group by 1 having size(collect_set(attr_key)) >= 1 order by utm_source_events asc
